import{_ as l,c as i,o as p,a4 as t,ae as s,af as o,ag as r,ah as a,ai as e,aj as _,ak as n}from"./chunks/framework.CX4ixmjU.js";const O=JSON.parse('{"title":"渲染流程","description":"","frontmatter":{},"headers":[],"relativePath":"browser/浏览器工作原理/4_渲染流程.md","filePath":"browser/浏览器工作原理/4_渲染流程.md"}'),c={name:"browser/浏览器工作原理/4_渲染流程.md"},u=t('<h1 id="渲染流程" tabindex="-1">渲染流程 <a class="header-anchor" href="#渲染流程" aria-label="Permalink to &quot;渲染流程&quot;">​</a></h1><p>渲染模块在执行过程会分为很多子模块，经过这些子阶段最后输出像素，这个处理流程叫渲染流水线，如下图：</p><p><img src="'+s+'" alt="渲染流水线"></p><p>按照渲染时间顺序，可以分为：构建DOM树、样式计算、布局阶段、分层、绘制、分块、光栅化和合成</p><ol><li><p><strong>构建DOM树</strong></p><p><img src="'+o+'" alt="DOM树结构"></p><ul><li>浏览器不能直接理解HTML，浏览器能够理解的是DOM树结构，所以渲染进程先把HTML转为DOM树</li><li>DOM树保存在内存中</li></ul></li><li><p><strong>样式计算</strong></p><ul><li><p>把CSS转换为浏览器能够理解的结构</p><p>浏览器也无法理解CSS样式，所以渲染引擎接收到CSS文本时，会执行一个转换操作，将CSS文本转换为浏览器可以理解的styleSheets</p><p>可以在控制台通过<code>document.styleSheets</code>打印查看其结构，并且具备查询和修改功能</p></li><li><p>转换样式表中的属性值，使其标准化</p><p><img src="'+r+'" alt="标准化转换"></p></li><li><p>计算出DOM树种每个节点具体样式</p><p>遵循CSS的继承规则和层叠规则，最终输出每个DOM节点的计算样式（也就是开发者工具的Elements标签的Computed子标签的内容）</p></li></ul></li><li><p><strong>布局阶段</strong></p><p>计算出DOM树种可见元素的几何位置，这个过程就是布局</p><ul><li>创建布局树</li></ul><p>遍历DOM树中所有可见元素节点，加到布局树</p><ul><li>布局计算</li></ul><p>计算布局树节点的坐标位置</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>布局操作时候，会把布局计算的结果重新写会布局树中，所以布局树即是输入内容也是输出内容，并没有清晰的将输入内容（比如插入的父节点中）和输出内容（比如元素自身的宽高）区分开来，Chrome团队正在开发的LayoutNG系统视图更清晰的分离输入和输出，让布局算法更简单</p></div></li><li><p><strong>分层</strong></p><ul><li><p>未特定节点生成专属图层（类似PS中的图层概念），生成一个对应的图层树</p></li><li><p>通过开发者工具的Layers标签可以可视化页面的分层情况</p></li><li><p>布局树的每个节点默认从属于父节点的图层，但是如果节点拥有<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/CSS_positioned_layout/Understanding_z-index/Stacking_context" target="_blank" rel="noreferrer">层叠上下文属性</a> 、需要剪裁（文字所显示区域超出元素区域），就会被创建专属图层</p></li></ul></li><li><p><strong>图层绘制</strong></p><ul><li><p>生成图层树后渲染引擎会对图层树中每个图层进行绘制</p></li><li><p>在这个阶段，就是把图层绘制拆分各个绘制指令列表并输出，可以在开发者工具的Layers标签，选择document层查看绘制列表</p></li></ul></li></ol><p><img src="'+a+'" alt="图层绘制"></p><ol start="6"><li><p><strong>栅格化操作</strong></p><ul><li><p>图层绘制列表准备好后，主线程会把列表提交给合成线程</p></li><li><p>合成线程会将图层划分为图块，按照视口（viewport）附近的图块来优先生成位图，图块生成位图的过程就叫做栅格化</p></li></ul></li></ol><p><img src="'+e+'" alt="图块"></p><ul><li>渲染进程维护了一个栅格化的线程池，所有栅格化都在线程池内执行，如果栅格化通过GPU加速生成，位图就会保存在GPU中，这就涉及到了跨进程操作</li></ul><p><img src="'+_+'" alt="GPU加速"></p><ol start="7"><li><p>合成和显示</p><ul><li>所有图块栅格化完成后，合成线程生成一个绘制图块的命令DrawQuad并提交给浏览器。浏览器viz组件接收DrawQuad命令将页面绘制到内存中，最后显示到屏幕上</li></ul></li></ol><p><strong>总结</strong></p><p><img src="'+n+'" alt="总结"></p><p><strong>渲染流水线--重排</strong></p><ul><li>更新元素的几何属性，比如宽、高，浏览器会触发重新布局，解析之后的一系列子阶段就叫重排</li><li>重排需要更新完整的渲染流程，所以开销很大</li></ul><p><strong>渲染流水线--重绘</strong></p><ul><li>更新元素的绘制属性，比如颜色，直接进入绘制阶段，在这之后的子阶段就叫重绘</li><li>相对于重排，重绘省去了布局和分层阶段</li></ul><p><strong>渲染流水线--合成</strong></p><ul><li>如果更改一个不需要布局也不需要绘制的属性，渲染引擎就会跳过布局和绘制，只执行后续合成操作，比如动画transform属性</li><li>相对于重绘和重排，绘制效率最高</li></ul>',19),g=[u];function m(d,S,h,D,f,C){return p(),i("div",null,g)}const P=l(c,[["render",m]]);export{O as __pageData,P as default};
